"""Determines the locale 'type' for a given locale name.

    Returns:
        (string) Always one of the following strings,
        'world' If the locale name refers to the world.
        'country' If the locale name looks like a country ID.
        'region' If the locale name looks like a region ID.
        'city' If the locale name looks like a city ID.
    """
def DetermineLocaleType(locale_str: Any) -> object {
    if (locale_str == 'world') {
        return 'world';
    }
    depth_map = {1: 'country', 2: 'region', 3: 'city'};
    depth = len(locale_str.split('_'));
    return depth_map[depth];
}

test_blocks:
test "t0" {
    assert (DetermineLocaleType('country') == 'country');;
}

test "t1" {
    assert (DetermineLocaleType('city_2_3') == 'city');;
}

test "t2" {
    assert (DetermineLocaleType('us_en') == 'region');;
}

test "t3" {
    assert (DetermineLocaleType('us_ca') == 'region');;
}

test "t4" {
    assert (DetermineLocaleType('world') == 'world');;
}

test "t5" {
    assert (DetermineLocaleType('us') == 'country');;
}

test "t6" {
    assert (DetermineLocaleType('region_2') == 'region');;
}
